arguments.command:
cd / && node -e "
const fs = require('fs');
const content = fs.readFileSync('/output/translation.md', 'utf-8');
const match = content.match(/\`\`\`braincode\n([\s\S]*?)\n\`\`\`/);
if (match) {
  const code = match[1];
  // Basic syntax check: MODE, ENTRYPOINT, TURN structure
  const checks = [
    { pattern: /MODE TRACE/, desc: 'MODE declaration' },
    { pattern: /ENTRYPOINT Conversation/, desc: 'ENTRYPOINT declaration' },
    { pattern: /CONVO Conversation/, desc: 'CONVO definition' },
    { pattern: /TURN t1 SPEAKER=USER/, desc: 'User turn' },
    { pattern: /TURN t2 SPEAKER=AGENT/, desc: 'Agent turn' },
    { pattern: /UTTER ask/, desc: 'Speech act' },
    { pattern: /RECORD ACTION/, desc: 'RECORD statements' },
    { pattern: /TERM /, desc: 'TERM constructors' }
  ];
  console.log('BrainCode structure checks:');
  checks.forEach(c => {
    console.log(c.pattern.test(code) ? '✓' : '✗', c.desc);
  });
  // Check for matching braces
  const opens = (code.match(/\{/g) || []).length;
  const closes = (code.match(/\}/g) || []).length;
  console.log('Brace matching:', opens === closes ? '✓' : '✗', \`(\${opens} open, \${closes} close)\`);
}
"
